INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','comparatives-and-superlatives','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"comparatives-and-superlatives","title":"Comparatives and superlatives","level":"A2","order":23,"summary":"Compare two things, identify an extreme in a group, and express equality.","learningGoals":["Comparing two","Comparing a group","Equal degree"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Comparing two","explanation":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","examples":["This route is shorter than that one.","The new seat is more comfortable."]},{"title":"Comparing a group","explanation":"Use the plus a superlative: often -est or most plus the adjective. Good becomes better/best; bad becomes worse/worst.","examples":["This is the safest path.","That was the best result."]},{"title":"Equal degree","explanation":"Use as plus the base adjective plus as for equality. Spelling may change in comparative and superlative forms.","examples":["The two boxes are as heavy as each other.","big → bigger → biggest"]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-comparisons","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"35dde1a3-9748-5ac4-a771-a3858fb88e49","topicSlug":"comparatives-and-superlatives","level":"A2","prompt":"Compare two trees: The first is ____ than the second. (tall)","choices":[{"id":"A","text":"most tall"},{"id":"B","text":"taller"},{"id":"C","text":"tall"},{"id":"D","text":"tallest"}],"answerId":"B","hint":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative. Focus on **comparative form** in this question.","explanation":"Use the comparative taller when comparing these two trees; than introduces the second.","keywords":[],"source":"seed","skill":"comparative-form","contextKey":"adjective-tall","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-comparisons","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"e59f7139db7a0610e10be396ca922b15c1a5bd47902e5eb928871196d9a5ef81","teaching":{"steps":["Identify what the question tests: **comparative form**. Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","Use the comparative taller when comparing these two trees; than introduces the second.","Choose **taller**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**most tall** is not the comparative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the comparative taller when comparing these two trees; than introduces the second.","B":"Use the comparative taller when comparing these two trees; than introduces the second.","C":"**tall** is not the comparative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the comparative taller when comparing these two trees; than introduces the second.","D":"**tallest** is not the comparative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the comparative taller when comparing these two trees; than introduces the second."}}},{"id":"076bf6b7-c072-5dfe-a830-4782ba49b70c","topicSlug":"comparatives-and-superlatives","level":"A2","prompt":"Compare all the trees in a group: The first is the ____. (tall)","choices":[{"id":"A","text":"tall"},{"id":"B","text":"taller"},{"id":"C","text":"more taller"},{"id":"D","text":"tallest"}],"answerId":"D","hint":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative. Focus on **superlative form** in this question.","explanation":"Use the superlative tallest after the to identify the extreme in the group.","keywords":[],"source":"seed","skill":"superlative-form","contextKey":"adjective-tall","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-comparisons","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"b3cc0b89be6d38ea34fad0020bc2f59c8b3b5e91238c4331a84d2dec91c2f20a","teaching":{"steps":["Identify what the question tests: **superlative form**. Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","Use the superlative tallest after the to identify the extreme in the group.","Choose **tallest**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**tall** is not the superlative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the superlative tallest after the to identify the extreme in the group.","B":"**taller** is not the superlative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the superlative tallest after the to identify the extreme in the group.","C":"**more taller** is not the superlative form required by the stated comparison; do not combine an -er/-est form with an extra more/most. Use the superlative tallest after the to identify the extreme in the group.","D":"Use the superlative tallest after the to identify the extreme in the group."}}},{"id":"f1c6a6bd-51a3-5e10-aa60-1905d40539ab","topicSlug":"comparatives-and-superlatives","level":"A2","prompt":"These two trees have the same quality: The first is as ____ as the second. (tall)","choices":[{"id":"A","text":"more taller"},{"id":"B","text":"tall"},{"id":"C","text":"taller"},{"id":"D","text":"tallest"}],"answerId":"B","hint":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative. Focus on **equality** in this question.","explanation":"The as ... as pattern uses the base adjective tall, not a comparative or superlative.","keywords":[],"source":"seed","skill":"equality","contextKey":"adjective-tall","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-comparisons","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"965b22840acde9a3233b6bc134c1cdc1b180a0d01d7e065c1773ef0ec96bdc11","teaching":{"steps":["Identify what the question tests: **equality**. Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","The as ... as pattern uses the base adjective tall, not a comparative or superlative.","Choose **tall**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"An equal comparison uses **as + adjective + as**. **more taller** does not supply the missing part of that pattern. The as ... as pattern uses the base adjective tall, not a comparative or superlative.","B":"The as ... as pattern uses the base adjective tall, not a comparative or superlative.","C":"An equal comparison uses **as + adjective + as**. **taller** does not supply the missing part of that pattern. The as ... as pattern uses the base adjective tall, not a comparative or superlative.","D":"An equal comparison uses **as + adjective + as**. **tallest** does not supply the missing part of that pattern. The as ... as pattern uses the base adjective tall, not a comparative or superlative."}}},{"id":"038c6d45-4d3e-5492-a6a8-1586f7479854","topicSlug":"comparatives-and-superlatives","level":"A2","prompt":"The first of these two trees is taller ____ the second.","choices":[{"id":"A","text":"then"},{"id":"B","text":"as"},{"id":"C","text":"that"},{"id":"D","text":"than"}],"answerId":"D","hint":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative. Focus on **than** in this question.","explanation":"After the comparative taller, use than to introduce the item being compared.","keywords":[],"source":"seed","skill":"than","contextKey":"adjective-tall","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-comparisons","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"031c8790363c28efc9c0bc18cdd62480374b22db866768ba57423599de0ca8a7","teaching":{"steps":["Identify what the question tests: **than**. Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","After the comparative taller, use than to introduce the item being compared.","Choose **than**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"The target of an ordinary comparative is introduced by **than**, not **then**. As belongs to an equality pattern; that is a different connector.","B":"The target of an ordinary comparative is introduced by **than**, not **as**. As belongs to an equality pattern; that is a